if (require.main === module) {
  (async () => {
    try {
      const input = await HookBase.parseInput();
      const hook = new TaskBlockerHook();
      await hook.execute(input);
      process.exit(0);
    } catch (error) {
      console.error(`Task blocker hook error: ${error.message}`);
      process.exit(1);
    }
  })();
}

